const express = require('express');
const { createHandler } = require('graphql-http/lib/use/express');
const { makeExecutableSchema } = require('@graphql-tools/schema');
const axios = require('axios');
const db = require('../db');

const app = express();
app.use(express.json());

const resolvers = {
  Query: {
    patientClinicalSummary: async (_, { patientId }, context) => {
      // Check physician-patient relationship before delegating to internal service
      const hasAccess = await db('practitioner_patient_assignments')
        .where({ practitioner_id: context.user.id, patient_id: patientId })
        .first();
      if (!hasAccess) {
        throw new Error('Unauthorized: No clinical relationship with patient');
      }

      const response = await axios.get(
        `http://internal-emr.mednet.local/api/v1/patients/${patientId}/summary`,
        { headers: { 'X-Gateway-Secret': process.env.GATEWAY_INTERNAL_SECRET } }
      );
      return response.data;
    }
  }
};

const schema = makeExecutableSchema({
  typeDefs: `type Query { patientClinicalSummary(patientId: String!): String }`,
  resolvers
});

app.all('/graphql', createHandler({ schema }));
module.exports = app;
